public class DeadlockDemo {static final Object A=new Object(),B=new Object(),SAFE_A=new Object(),SAFE_B=new Object();static void unsafe(boolean first){Object x=first?A:B,y=first?B:A;synchronized(x){try{Thread.sleep(100);}catch(InterruptedException e){}synchronized(y){System.out.println("Unsafe section completed");}}}static void safe(){synchronized(SAFE_A){synchronized(SAFE_B){System.out.println("Safe section completed");}}}public static void main(String[] args)throws Exception{Thread t1=new Thread(()->unsafe(true)),t2=new Thread(()->unsafe(false));t1.setDaemon(true);t2.setDaemon(true);t1.start();t2.start();Thread.sleep(300);System.out.println("Opposite lock order may deadlock (demo threads are daemon)");Thread s1=new Thread(DeadlockDemo::safe),s2=new Thread(DeadlockDemo::safe);s1.start();s2.start();s1.join();s2.join();}}
